-- TRIP CHAT SWITCHES REHEARSAL (generated from supabase/rehearsal/rehearsal_chat_settings.template.sql + the migration by scripts/build-rehearsal.mjs; do not edit this file by hand).
-- ONE batch that applies 20261130090000_chat_settings.sql (the three trip-chat migrations 20261129* are already live and are NOT embedded), exercises the switches on the private test trip,
-- then ENDS WITH AN ERROR so that EVERYTHING ROLLS BACK. Result: "REHEARSAL PASS [...]" or "REHEARSAL FAIL [...]". Impersonation is claims + SET LOCAL ROLE (authenticated / anon), the technique that
-- passed on live; the real site admin and a real organiser / member of the test trip are used, and no user row is changed.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TEMP TABLE _rehearsal (step text, ok boolean, detail text);
CREATE TEMP TABLE _rh_ctx (k text PRIMARY KEY, v text);
CREATE FUNCTION pg_temp.rh_rec(p_step text, p_ok boolean, p_detail text) RETURNS void LANGUAGE sql AS $f$
  INSERT INTO _rehearsal VALUES (p_step, coalesce(p_ok, false), left(p_detail, 400))
$f$;
CREATE FUNCTION pg_temp.rh_ctx(p_k text) RETURNS text LANGUAGE sql STABLE AS $f$
  SELECT v FROM _rh_ctx WHERE k = p_k
$f$;
-- run ONE statement as a signed-in person (p_uid, role authenticated) or as anon (p_uid NULL, p_role anon); a select returns its single jsonb column, anything else just runs.
-- Never raises: {"ok":true,"r":<result>} or {"ok":false,"code":<sqlstate>,"hint":<hint>}
CREATE FUNCTION pg_temp.rh_call(p_uid uuid, p_role text, p_sql text) RETURNS jsonb LANGUAGE plpgsql AS $f$
DECLARE
  v_r jsonb; v_hint text;
BEGIN
  PERFORM set_config('request.jwt.claims', CASE WHEN p_uid IS NULL THEN json_build_object('role', p_role)::text ELSE json_build_object('sub', p_uid, 'role', p_role)::text END, true);
  PERFORM set_config('request.jwt.claim.sub', coalesce(p_uid::text, ''), true);
  PERFORM set_config('request.jwt.claim.role', p_role, true);
  BEGIN
    EXECUTE format('SET LOCAL ROLE %I', p_role);
    IF p_sql ~* '^\s*select' THEN EXECUTE p_sql INTO v_r; ELSE EXECUTE p_sql; END IF;
    RESET ROLE;
    RETURN jsonb_build_object('ok', true, 'r', v_r);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    RESET ROLE;
    RETURN jsonb_build_object('ok', false, 'code', SQLSTATE, 'hint', v_hint);
  END;
END
$f$;

-- ===== 0a. BEFORE: the names are free and the helpers are there ================================================================================================
DO $rh$
DECLARE
  v_n integer;
BEGIN
  BEGIN
    SELECT count(*) INTO v_n FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname IN ('get_chat_availability', 'set_trip_chat_settings', 'admin_get_chat_settings', 'admin_set_chat_settings', '_chat_effective', '_chat_trip_upcoming');
    PERFORM pg_temp.rh_rec('pre.names_free', v_n = 0 AND to_regclass('public.chat_site_settings') IS NULL AND to_regclass('public.trip_chat_settings') IS NULL, 'tables and functions absent: ' || v_n);
    PERFORM pg_temp.rh_rec('pre.helpers', to_regprocedure('public.is_trip_participant(uuid,uuid)') IS NOT NULL AND to_regclass('public.chat_actions') IS NOT NULL AND to_regclass('public.trip_chat_threads') IS NOT NULL
      AND (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'trips' AND column_name IN ('start_date', 'end_date') AND data_type = 'date') = 2,
      'is_trip_participant, chat_actions, trip_chat_threads, trips.start_date/end_date (date)');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('pre', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== BEGIN MIGRATION (verbatim copy of supabase/migrations/20261130090000_chat_settings.sql) =====
@@MIGRATION@@
-- ===== END MIGRATION =====

-- ===== 0b. the people: the real site admin, an organiser and a plain member of the test trip, someone who is not on it ===========================================
-- The live test trip has only two people (the site admin as organiser + one participant), so the organiser who is NOT the admin and/or the plain member may not exist. Whatever is missing is
-- created INSIDE this transaction (rolled back with everything else): an existing non-admin user who is not on the trip is added to it by cloning an existing participant row (the same technique as
-- the phase-4 throwaway trip), with the missing role. A real organiser / member is used when the trip has one. Anything that cannot be set up makes setup.people FAIL and the behaviour steps are skipped.
-- The temporary rows are plain INSERTs by the owner (no JWT); side_effects.no_notifications at the end proves no notification (and so no mail) came out of them.
DO $rh$
DECLARE
  v_trip constant uuid := 'be551bc4-a524-4b6a-a0c9-b74a7168ced4';
  v_admin uuid; v_org uuid; v_mem uuid; v_out uuid; v_cand uuid; v_added text := ''; v_tpl public.trip_participants; v_n integer; v_cnt_n integer; v_cnt_a integer;
BEGIN
  BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.trips WHERE id = v_trip) THEN PERFORM pg_temp.rh_rec('setup.trip', false, 'test trip not found'); RETURN; END IF;
    SELECT count(*) INTO v_cnt_n FROM public.notifications;
    SELECT count(*) INTO v_cnt_a FROM public.activity_feed;
    INSERT INTO _rh_ctx VALUES ('notif0', v_cnt_n::text), ('act0', v_cnt_a::text);
    SELECT u.id INTO v_admin FROM public.users u WHERE u.role::text = 'admin' ORDER BY u.id LIMIT 1;
    SELECT tp.user_id INTO v_org FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.role::text = 'organizer' AND tp.active AND tp.user_id IS DISTINCT FROM v_admin ORDER BY tp.user_id LIMIT 1;
    SELECT tp.user_id INTO v_mem FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.role::text <> 'organizer' AND tp.active AND tp.user_id IS DISTINCT FROM v_admin AND tp.user_id IS DISTINCT FROM v_org ORDER BY tp.user_id LIMIT 1;
    SELECT * INTO v_tpl FROM public.trip_participants tp WHERE tp.trip_id = v_trip ORDER BY (tp.user_id IS NOT DISTINCT FROM v_admin), tp.user_id LIMIT 1;
    -- missing organiser, then missing member: an existing non-admin user who is not on the trip yet, added to it for this transaction only
    FOR v_n IN 1..2 LOOP
      IF (v_n = 1 AND v_org IS NOT NULL) OR (v_n = 2 AND v_mem IS NOT NULL) THEN CONTINUE; END IF;
      SELECT u.id INTO v_cand FROM public.users u WHERE u.role::text <> 'admin' AND NOT EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = u.id) ORDER BY u.id LIMIT 1;
      IF v_cand IS NULL THEN CONTINUE; END IF;
      IF v_tpl.trip_id IS NOT NULL THEN
        INSERT INTO public.trip_participants SELECT (jsonb_populate_record(NULL::public.trip_participants, to_jsonb(v_tpl) || jsonb_build_object('user_id', v_cand, 'role', CASE WHEN v_n = 1 THEN 'organizer' ELSE 'participant' END, 'active', true))).*;
      ELSE
        INSERT INTO public.trip_participants (trip_id, user_id, role, active) VALUES (v_trip, v_cand, (CASE WHEN v_n = 1 THEN 'organizer' ELSE 'participant' END)::public.participant_role, true);
      END IF;
      IF v_n = 1 THEN v_org := v_cand; v_added := v_added || 'organiser '; ELSE v_mem := v_cand; v_added := v_added || 'member '; END IF;
    END LOOP;
    SELECT u.id INTO v_out FROM public.users u WHERE u.role::text <> 'admin' AND NOT EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = u.id) ORDER BY u.id LIMIT 1;
    -- the roles really are what the steps assume (read back, not assumed)
    IF v_org IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = v_org AND tp.role::text = 'organizer' AND tp.active) THEN v_org := NULL; END IF;
    IF v_mem IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = v_mem AND tp.role::text <> 'organizer' AND tp.active) THEN v_mem := NULL; END IF;
    INSERT INTO _rh_ctx VALUES ('trip', v_trip::text);
    IF v_admin IS NOT NULL THEN INSERT INTO _rh_ctx VALUES ('admin', v_admin::text); END IF;
    IF v_org IS NOT NULL THEN INSERT INTO _rh_ctx VALUES ('org', v_org::text); END IF;
    IF v_mem IS NOT NULL THEN INSERT INTO _rh_ctx VALUES ('mem', v_mem::text); END IF;
    IF v_out IS NOT NULL THEN INSERT INTO _rh_ctx VALUES ('out', v_out::text); END IF;
    PERFORM pg_temp.rh_rec('setup.people', v_admin IS NOT NULL AND v_org IS NOT NULL AND v_mem IS NOT NULL AND v_out IS NOT NULL
      AND v_admin IS DISTINCT FROM v_org AND v_admin IS DISTINCT FROM v_mem AND v_org IS DISTINCT FROM v_mem AND v_out NOT IN (v_admin, v_org, v_mem),
      format('site admin %s; active organiser (not the admin) %s; plain member %s; outsider %s; added to the trip inside the transaction: %s', v_admin IS NOT NULL, v_org IS NOT NULL, v_mem IS NOT NULL, v_out IS NOT NULL, coalesce(nullif(trim(v_added), ''), 'nobody')));
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('setup.people', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 1. structure and seed ===================================================================================================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_bad text := ''; r record; v_site record; v_tr record;
BEGIN
  BEGIN
    PERFORM pg_temp.rh_rec('struct.tables', (SELECT count(*) FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relname IN ('chat_site_settings', 'trip_chat_settings') AND c.relrowsecurity) = 2
      AND (SELECT count(*) FROM pg_policies WHERE tablename IN ('chat_site_settings', 'trip_chat_settings')) = 0
      AND NOT has_table_privilege('authenticated', 'public.chat_site_settings', 'SELECT') AND NOT has_table_privilege('authenticated', 'public.trip_chat_settings', 'INSERT')
      AND NOT has_table_privilege('authenticated', 'public.trip_chat_settings', 'UPDATE') AND NOT has_table_privilege('anon', 'public.trip_chat_settings', 'SELECT') AND has_table_privilege('service_role', 'public.trip_chat_settings', 'SELECT'),
      'RLS on both, no policy, no client privilege, service role can read');
    FOR r IN SELECT * FROM (VALUES ('public.get_chat_availability(uuid)', true), ('public.set_trip_chat_settings(uuid,text,text)', true), ('public.admin_get_chat_settings()', true), ('public.admin_set_chat_settings(text,text)', true),
      ('public._chat_effective(text,text,text,text,date,date)', false), ('public._chat_trip_upcoming(date,date)', false), ('public._chat_availability_json(uuid,uuid)', false), ('public._chat_admin_json()', false), ('public._chat_is_site_admin(uuid)', false)) AS x(f, want_auth) LOOP
      IF has_function_privilege('anon', r.f, 'EXECUTE') OR has_function_privilege('authenticated', r.f, 'EXECUTE') IS DISTINCT FROM r.want_auth THEN v_bad := v_bad || r.f || ' '; END IF;
    END LOOP;
    PERFORM pg_temp.rh_rec('struct.function_privileges', v_bad = '', CASE WHEN v_bad = '' THEN '4 RPCs: authenticated only; 5 helpers: nobody' ELSE 'wrong: ' || v_bad END);
    SELECT * INTO v_site FROM public.chat_site_settings;
    SELECT * INTO v_tr FROM public.trip_chat_settings WHERE trip_id = v_trip;
    PERFORM pg_temp.rh_rec('seed.site', (SELECT count(*) FROM public.chat_site_settings) = 1 AND v_site.mode = 'actions' AND v_site.actions_scope = 'upcoming', format('mode=%s scope=%s', v_site.mode, v_site.actions_scope));
    PERFORM pg_temp.rh_rec('seed.test_trip', (SELECT count(*) FROM public.trip_chat_settings) = 1 AND v_tr.chat = 'inherit' AND v_tr.actions = 'on', format('only the test trip has a row: chat=%s actions=%s', v_tr.chat, v_tr.actions));
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('struct', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
END
$rh$;

-- ===== 2. reading and denial ===================================================================================================================================
DO $rh$
DECLARE
  v_admin uuid := pg_temp.rh_ctx('admin')::uuid; v_org uuid := pg_temp.rh_ctx('org')::uuid; v_mem uuid := pg_temp.rh_ctx('mem')::uuid; v_out uuid := pg_temp.rh_ctx('out')::uuid;
  v_r jsonb; v_t text := quote_literal(pg_temp.rh_ctx('trip'));
BEGIN
  IF v_admin IS NULL OR v_org IS NULL OR v_mem IS NULL OR v_out IS NULL THEN RETURN; END IF;
  v_r := pg_temp.rh_call(v_mem, 'authenticated', 'select public.get_chat_availability(' || v_t || ')');
  PERFORM pg_temp.rh_rec('read.member', (v_r ->> 'ok')::boolean AND (v_r #>> '{r,chat}')::boolean AND (v_r #>> '{r,actions}')::boolean AND NOT (v_r #>> '{r,can_manage}')::boolean AND NOT (v_r #>> '{r,can_force_on}')::boolean AND v_r #>> '{r,trip,actions}' = 'on',
    'a member: chat true, actions true (forced on by the seed), cannot manage; ' || left(v_r::text, 160));
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'select public.get_chat_availability(' || v_t || ')');
  PERFORM pg_temp.rh_rec('read.organiser', (v_r #>> '{r,can_manage}')::boolean AND NOT (v_r #>> '{r,can_force_on}')::boolean, 'the organiser can manage, not force on');
  v_r := pg_temp.rh_call(v_admin, 'authenticated', 'select public.get_chat_availability(' || v_t || ')');
  PERFORM pg_temp.rh_rec('read.admin', (v_r #>> '{r,can_manage}')::boolean AND (v_r #>> '{r,can_force_on}')::boolean, 'the site admin can manage and force on');
  v_r := pg_temp.rh_call(NULL, 'anon', 'select public.get_chat_availability(' || v_t || ')');
  PERFORM pg_temp.rh_rec('deny.anon', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'code' = '42501', coalesce(v_r ->> 'code', '') || ' ' || coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_out, 'authenticated', 'select public.get_chat_availability(' || v_t || ')');
  PERFORM pg_temp.rh_rec('deny.outsider', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'forbidden', coalesce(v_r ->> 'code', '') || ' ' || coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', ''off'', NULL)');
  PERFORM pg_temp.rh_rec('deny.member_set', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'forbidden', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'update public.chat_site_settings set mode = ''off''');
  PERFORM pg_temp.rh_rec('deny.direct_site_write', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'code' = '42501', coalesce(v_r ->> 'code', ''));
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'select to_jsonb(count(*)) from public.trip_chat_settings');
  PERFORM pg_temp.rh_rec('deny.direct_trip_read', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'code' = '42501', coalesce(v_r ->> 'code', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', 'select public.admin_get_chat_settings()');
  PERFORM pg_temp.rh_rec('deny.member_admin_get', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'forbidden', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'select public.admin_set_chat_settings(''off'', NULL)');
  PERFORM pg_temp.rh_rec('deny.organiser_admin_set', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'forbidden' AND (SELECT mode FROM public.chat_site_settings) = 'actions', coalesce(v_r ->> 'hint', ''));
END
$rh$;

-- ===== 3. setting: organiser limits, admin force, frozen trip, site mode, effective values =====================================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_admin uuid := pg_temp.rh_ctx('admin')::uuid; v_org uuid := pg_temp.rh_ctx('org')::uuid; v_mem uuid := pg_temp.rh_ctx('mem')::uuid;
  v_r jsonb; v_t text := quote_literal(pg_temp.rh_ctx('trip')); v_trips integer; v_listed integer; v_frozen boolean; v_skip boolean := false; v_card uuid;
BEGIN
  IF v_admin IS NULL OR v_org IS NULL OR v_mem IS NULL THEN RETURN; END IF;
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', ''off'', ''off'')');
  PERFORM pg_temp.rh_rec('organiser.switch_off', (v_r ->> 'ok')::boolean AND NOT (v_r #>> '{r,chat}')::boolean AND NOT (v_r #>> '{r,actions}')::boolean AND v_r #>> '{r,trip,chat}' = 'off', 'chat and actions off for their trip: ' || left(v_r::text, 140));
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', NULL, ''on'')');
  PERFORM pg_temp.rh_rec('organiser.cannot_force_on', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'admin_only', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', ''inherit'', ''inherit'')');
  PERFORM pg_temp.rh_rec('organiser.back_to_inherit', (v_r ->> 'ok')::boolean AND (v_r #>> '{r,chat}')::boolean AND v_r #>> '{r,trip,actions}' = 'inherit', 'chat back on; actions follow the site: ' || (v_r #>> '{r,actions}'));
  v_r := pg_temp.rh_call(v_org, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', ''on'', NULL)');
  PERFORM pg_temp.rh_rec('organiser.invalid_value', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'invalid', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_admin, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', NULL, ''on'')');
  PERFORM pg_temp.rh_rec('admin.force_on', (v_r ->> 'ok')::boolean AND (v_r #>> '{r,actions}')::boolean AND v_r #>> '{r,trip,actions}' = 'on', 'forced on, actions true');
  -- frozen trip: frozen inside the transaction by the owner (no JWT), then the organiser still may change the switches
  BEGIN
    PERFORM set_config('request.jwt.claims', '', true); PERFORM set_config('request.jwt.claim.sub', '', true); PERFORM set_config('request.jwt.claim.role', '', true);
    SELECT settlement_snapshot IS NOT NULL INTO v_frozen FROM public.trips WHERE id = v_trip;
    IF NOT v_frozen THEN
      BEGIN
        UPDATE public.trips SET settlement_snapshot = '{"transactions":[]}' WHERE id = v_trip;
      EXCEPTION WHEN OTHERS THEN
        v_skip := true;
        PERFORM pg_temp.rh_rec('frozen.organiser_can_set', true, 'SKIPPED: the database would not let this script freeze the test trip (' || SQLSTATE || '); the frozen case is covered by the pglite suite');
      END;
    END IF;
    IF NOT v_skip THEN
      v_r := pg_temp.rh_call(v_org, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', ''off'', NULL)');
      PERFORM pg_temp.rh_rec('frozen.organiser_can_set', (v_r ->> 'ok')::boolean AND NOT (v_r #>> '{r,chat}')::boolean, CASE WHEN v_frozen THEN 'the trip was already frozen' ELSE 'froze the test trip inside the transaction' END || ': ' || left(v_r::text, 120));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('frozen.organiser_can_set', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  PERFORM pg_temp.rh_call(v_org, 'authenticated', 'select public.set_trip_chat_settings(' || v_t || ', ''inherit'', NULL)');
  v_r := pg_temp.rh_call(v_admin, 'authenticated', 'select public.admin_set_chat_settings(''answers'', NULL)');
  PERFORM pg_temp.rh_rec('site.answers', (v_r ->> 'ok')::boolean AND coalesce((SELECT (e ->> 'effective_chat')::boolean AND NOT (e ->> 'effective_actions')::boolean FROM jsonb_array_elements(v_r #> '{r,trips}') e WHERE e ->> 'trip_id' = pg_temp.rh_ctx('trip')), false),
    'mode answers: the test trip (forced on) answers but proposes nothing');
  v_r := pg_temp.rh_call(v_mem, 'authenticated', 'select public.get_chat_availability(' || v_t || ')');
  PERFORM pg_temp.rh_rec('site.answers_member_view', (v_r #>> '{r,chat}')::boolean AND NOT (v_r #>> '{r,actions}')::boolean AND v_r #>> '{r,site,mode}' = 'answers', 'a member sees chat true, actions false');
  -- a card proposed earlier cannot be confirmed once actions are off (begin_chat_action is replaced by this migration); mode is 'answers' here
  BEGIN
    INSERT INTO public.chat_actions (trip_id, user_id, turn_id, kind, params, preview, basis, requires, expires_at) VALUES (v_trip, v_mem, gen_random_uuid(), 'add_todo', '{"title":"x"}', '{"line":"x"}', '{"v":1}', 'tap', now() + interval '1 day') RETURNING id INTO v_card;
    v_r := pg_temp.rh_call(v_mem, 'authenticated', 'select public.begin_chat_action(''' || v_card || ''')');
    PERFORM pg_temp.rh_rec('begin.refused_when_actions_off', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'actions_off' AND (SELECT status FROM public.chat_actions WHERE id = v_card) = 'proposed', 'confirming is refused (actions_off) and the card stays proposed');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('begin.refused_when_actions_off', false, 'ERROR ' || SQLSTATE || ' ' || SQLERRM);
  END;
  v_r := pg_temp.rh_call(v_admin, 'authenticated', 'select public.admin_set_chat_settings(''off'', ''all'')');
  v_r := pg_temp.rh_call(v_mem, 'authenticated', 'select public.get_chat_availability(' || v_t || ')');
  PERFORM pg_temp.rh_rec('site.off', NOT (v_r #>> '{r,chat}')::boolean AND NOT (v_r #>> '{r,actions}')::boolean, 'mode off: chat false and actions false, even for the forced-on trip');
  v_r := pg_temp.rh_call(v_admin, 'authenticated', 'select public.admin_set_chat_settings(''actions'', ''all'')');
  SELECT count(*) INTO v_trips FROM public.trips;
  v_listed := jsonb_array_length(v_r #> '{r,trips}');
  PERFORM pg_temp.rh_rec('admin.list_all_trips', (v_r ->> 'ok')::boolean AND v_listed = v_trips AND v_r #>> '{r,actions_scope}' = 'all', format('lists %s of %s trips; scope all', v_listed, v_trips));
  v_r := pg_temp.rh_call(v_admin, 'authenticated', 'select public.admin_set_chat_settings(''loud'', NULL)');
  PERFORM pg_temp.rh_rec('admin.invalid', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'invalid', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_admin, 'authenticated', 'update public.chat_site_settings set mode = mode');
  PERFORM pg_temp.rh_rec('admin.direct_write_refused', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'code' = '42501', 'even an admin writes only through the RPCs');
  BEGIN
    DELETE FROM public.chat_site_settings;
    PERFORM pg_temp.rh_rec('site.singleton_undeletable', false, 'DELETE NOT refused');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('site.singleton_undeletable', SQLSTATE = 'P0001', SQLSTATE);
  END;
  PERFORM pg_temp.rh_rec('info.seed_effect', true, format('at the end (mode actions, scope upcoming, trips as they are now) %s of %s trips would have actions on',
    (SELECT count(*) FROM public.trips t WHERE (public._chat_effective('actions', 'upcoming', 'inherit', coalesce((SELECT c.actions FROM public.trip_chat_settings c WHERE c.trip_id = t.id), 'inherit'), t.start_date, t.end_date) ->> 'actions')::boolean), v_trips));
END
$rh$;

-- ===== side effects: the temporary people and the settings calls sent nothing ===============================================================================
DO $rh$
DECLARE
  v_n integer; v_a integer;
BEGIN
  IF pg_temp.rh_ctx('notif0') IS NULL THEN PERFORM pg_temp.rh_rec('side_effects.no_notifications', false, 'no baseline (setup did not run)'); RETURN; END IF;
  SELECT count(*) INTO v_n FROM public.notifications;
  SELECT count(*) INTO v_a FROM public.activity_feed;
  PERFORM pg_temp.rh_rec('side_effects.no_notifications', v_n = pg_temp.rh_ctx('notif0')::integer, format('notifications before=%s now=%s (adding the temporary people and every call above wrote none; the database never sends mail)', pg_temp.rh_ctx('notif0'), v_n));
  PERFORM pg_temp.rh_rec('info.activity_rows', true, format('activity_feed before=%s now=%s (informational; rolled back)', pg_temp.rh_ctx('act0'), v_a));
END
$rh$;

-- ===== FINAL: report through the error message (this also rolls everything back) ===============================================================================
DO $rh$
DECLARE
  v_all boolean; v_json text; v_failed integer; v_total integer;
BEGIN
  SELECT coalesce(bool_and(ok), false), count(*) FILTER (WHERE NOT ok), count(*) INTO v_all, v_failed, v_total FROM _rehearsal;
  SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 160)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, CASE WHEN ok THEN 0 ELSE 90 END)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  END IF;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 90)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal WHERE NOT ok;
    v_json := left(v_json, 5800) || ' (only failing steps shown)';
  END IF;
  RAISE EXCEPTION '%', 'REHEARSAL ' || CASE WHEN v_all THEN 'PASS' ELSE 'FAIL' END || ' (' || v_total || ' steps, ' || v_failed || ' failed) ' || v_json;
END
$rh$;
ROLLBACK;
